INSERT IGNORE INTO recomendacoes (criterio, descricao, ativo, created_at, updated_at) VALUES
('LISO_CLARA_OVAL_CLASSICO', 'Para cabelos lisos com pele clara e rosto oval, recomendamos um corte clássico em camadas médias com franja lateral. Este estilo valoriza a simetria natural e cria um visual elegante e atemporal. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
